@font-face{font-family:Orbitron;src:url('/assets/fonts/orbitron.woff2') format('woff2');font-weight:400 900;font-display:swap}
@font-face{font-family:Rajdhani;src:url('/assets/fonts/rajdhani-400.woff2') format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:Rajdhani;src:url('/assets/fonts/rajdhani-700.woff2') format('woff2');font-weight:600 900;font-display:swap}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#070b13;color:#eef6ff;font-family:Rajdhani,Arial,sans-serif}
button{font:inherit;color:inherit}
#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#080e18}
#game{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 42%,rgba(2,5,12,.3) 100%),linear-gradient(0deg,rgba(5,9,16,.22),transparent 25%,transparent 75%,rgba(5,9,16,.4))}
.hud{position:absolute;z-index:3;pointer-events:none}
.hidden{display:none!important}
#topbar{inset:0 0 auto;height:92px;display:flex;align-items:center;padding:0 4.3%;border-bottom:1px solid rgba(152,194,228,.12);background:linear-gradient(180deg,rgba(5,10,19,.78),transparent)}
.brand-mark{display:flex;align-items:center;gap:11px;width:33%;font:10px Orbitron,sans-serif;letter-spacing:1.6px;color:#99adbf}
.brand-dot,.status-pip{width:7px;height:7px;border-radius:50%;background:#56e6dc;box-shadow:0 0 12px #56e6dc}
.world-readout{display:flex;flex-direction:column;align-items:center;gap:2px;flex:1;font:14px Orbitron,sans-serif;letter-spacing:1.6px}
.world-readout #world-name{font-size:11px;color:#9eb2c7;letter-spacing:2px}
.eyebrow{font:9px Orbitron,sans-serif;letter-spacing:1.4px;color:#71869c}
.world-readout .eyebrow b{color:#58e8de}
.artifact-readout{width:33%;display:flex;align-items:flex-end;flex-direction:column;gap:8px}
.artifact-readout .eyebrow{font-size:8px}
.artifact-readout #artifact-slots{display:flex;gap:6px}
#artifact-slots i{width:13px;height:13px;display:block;border:1px solid rgba(106,145,174,.42);transform:rotate(45deg);background:rgba(9,17,28,.8);transition:.3s}
#artifact-slots i.filled{background:#59e8de;border-color:#c3fffb;box-shadow:0 0 14px #59e8de}
.mission{left:4.3%;top:120px;display:flex;gap:13px;align-items:center;padding:12px 17px 11px 12px;border:1px solid rgba(107,159,195,.23);background:linear-gradient(110deg,rgba(7,15,27,.8),rgba(7,15,27,.14));min-width:210px}
.mission-icon{font-size:26px;color:#60e9df}
.mission p{font-size:18px;font-weight:700;margin:3px 0 -2px;letter-spacing:.4px}
.mission small{font-size:12px;color:#62e8dd;letter-spacing:1px}
.health-panel{top:120px;right:4.3%;width:180px;display:grid;grid-template-columns:1fr 32px;gap:8px;align-items:center}
.health-panel .eyebrow{grid-column:span 2}
.health-panel b{font:12px Orbitron;color:#e8f4fd}
.health-track,.boss-track{height:5px;background:rgba(151,183,208,.2);overflow:hidden}
.health-track div{height:100%;width:100%;background:#54dfc9;box-shadow:0 0 12px #54dfc9;transition:width .2s}
.boss-panel{position:absolute;z-index:4;top:31px;left:50%;transform:translateX(-50%);width:min(440px,65vw);text-align:center}
.boss-name{display:flex;flex-direction:column;gap:4px;margin-bottom:8px}
.boss-name span{font:8px Orbitron;letter-spacing:2px;color:#f68a8a}
.boss-name b{font:16px Orbitron;letter-spacing:3px}
.boss-name em{font:9px Orbitron;color:#ff7373;font-style:normal;letter-spacing:2px}
.boss-track{height:7px;background:rgba(255,255,255,.16)}
.boss-track div{height:100%;width:100%;background:linear-gradient(90deg,#ff4a55,#ffac72);box-shadow:0 0 14px #ff4455;transition:width .35s}
.crosshair{position:absolute;z-index:2;left:50%;top:50%;width:23px;height:23px;transform:translate(-50%,-50%);pointer-events:none;opacity:.82}
.crosshair i{position:absolute;left:10px;top:0;width:1px;height:6px;background:#a7fff5}
.crosshair i:nth-child(3){top:auto;bottom:0}
.crosshair em{position:absolute;top:10px;left:0;width:6px;height:1px;background:#a7fff5}
.crosshair b{position:absolute;top:10px;right:0;width:6px;height:1px;background:#a7fff5}
.toast{position:absolute;z-index:5;top:25%;left:50%;transform:translate(-50%,-6px);opacity:0;transition:.3s;pointer-events:none;padding:10px 18px;border:1px solid rgba(110,236,227,.38);background:rgba(5,14,24,.82);font:10px Orbitron;letter-spacing:1.6px;color:#b9fffa;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.hit-flash,.hurt-flash{position:absolute;inset:0;pointer-events:none;opacity:0}
.hit-flash{background:radial-gradient(circle at center,rgba(147,255,233,.3),transparent 35%)}
.hit-flash.active{animation:hit .14s}
.hurt-flash{box-shadow:inset 0 0 120px rgba(255,35,48,.85)}
.hurt-flash.active{animation:hurt .3s}
@keyframes hit{50%{opacity:1}
}
@keyframes hurt{30%{opacity:1}
}
.prompt{position:absolute;z-index:3;left:50%;top:61%;transform:translateX(-50%);font:11px Orbitron;color:#68fff0;letter-spacing:1px;text-shadow:0 0 12px #48ffe9}
.prompt span{color:white}
.controls-hint{left:50%;bottom:22px;transform:translateX(-50%);font:9px Orbitron;letter-spacing:1.2px;color:rgba(197,218,237,.63);white-space:nowrap}
.controls-hint i{color:#56e6dc;font-style:normal;padding:0 7px}
.overlay{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 68% 42%,rgba(19,45,66,.45),transparent 46%),linear-gradient(115deg,rgba(6,11,20,.96),rgba(7,14,24,.91) 46%,rgba(5,11,18,.82));transition:opacity .5s,visibility .5s}
.overlay.dismissed{opacity:0;visibility:hidden;pointer-events:none}
.overlay-grid{position:absolute;inset:0;opacity:.16;background-image:linear-gradient(rgba(99,159,188,.18) 1px,transparent 1px),linear-gradient(90deg,rgba(99,159,188,.18) 1px,transparent 1px);background-size:70px 70px;mask-image:linear-gradient(90deg,transparent 4%,black 75%)}
.overlay-glow{position:absolute;width:520px;height:520px;right:5%;top:8%;border-radius:50%;background:radial-gradient(circle,rgba(28,219,199,.13),rgba(45,105,152,.06) 34%,transparent 70%);filter:blur(16px)}
.overlay-content{position:relative;width:min(940px,84vw);z-index:1}
.title-kicker{display:flex;align-items:center;gap:11px;font:10px Orbitron;letter-spacing:2.1px;color:#91acbd}
.title-kicker .status-pip{width:6px;height:6px;animation:pulse 1.8s infinite}
@keyframes pulse{50%{opacity:.35;box-shadow:0 0 3px #56e6dc}
}
h1{font:900 clamp(58px,9vw,112px)/.93 Orbitron,sans-serif;letter-spacing:-5px;margin:27px 0 22px;color:#f1f5f8;text-shadow:0 4px 40px rgba(86,232,218,.08)}
h1 span{color:#5ce4d9}
.title-rule{display:flex;align-items:center;gap:14px;width:min(390px,80vw);font:10px Orbitron;letter-spacing:2px;color:#c3d6e5}
.title-rule i{height:1px;background:rgba(93,220,210,.48);flex:1}
.title-rule i:first-child{max-width:48px;height:2px;background:#5ce4d9}
.title-copy{margin:20px 0 25px;color:#9cacb9;font-size:18px;letter-spacing:.4px}
.primary-button{display:flex;align-items:center;justify-content:space-between;gap:46px;padding:0 18px;height:49px;min-width:225px;border:1px solid #65eee0;background:#59ded3;color:#08131b;font:700 11px Orbitron;letter-spacing:1px;cursor:pointer;transition:.2s}
.primary-button:hover{background:#a4fff6;box-shadow:0 0 25px rgba(91,236,220,.38);transform:translateY(-2px)}
.primary-button b{font-size:17px}
.title-footer{display:flex;gap:28px;margin-top:55px;color:#62788a;font:8px Orbitron;letter-spacing:1.3px}
.title-footer span:last-child{color:#6be4da}
.overlay-bottom{position:absolute;bottom:24px;left:4.3%;right:4.3%;display:flex;justify-content:space-between;color:#4f6271;font:8px Orbitron;letter-spacing:1.4px}
.overlay-content.mode-card{text-align:left}
.overlay-content.mode-card h1{font-size:clamp(35px,5vw,62px);letter-spacing:-2px;margin:17px 0 14px}
.overlay-content.mode-card .title-copy{max-width:560px;line-height:1.6}
.card-worlds{display:flex;gap:8px;flex-wrap:wrap;margin:23px 0 29px}
.world-chip{padding:9px 11px;border:1px solid rgba(119,168,196,.25);font:9px Orbitron;color:#8aa1b3;letter-spacing:.6px}
.world-chip.current{border-color:rgba(92,228,217,.6);color:#72f5e9;background:rgba(40,151,145,.08)}
.world-chip.done{color:#5ce4d9;border-color:rgba(92,228,217,.35)}
.touch-controls{position:absolute;z-index:4;inset:auto 0 18px;display:none;pointer-events:none;align-items:flex-end;justify-content:space-between;padding:0 22px}
.move-pad,.fire-button,.dash-button{pointer-events:auto}
.move-pad>button,.move-pad div button,.dash-button,.fire-button{border:1px solid rgba(132,211,219,.4);background:rgba(5,16,27,.62);color:#d8fff9;backdrop-filter:blur(8px);touch-action:none}
.move-pad>button{margin:0 auto 5px;display:block}
.move-pad div{display:flex;gap:4px}
.move-pad button{width:42px;height:38px;border-radius:7px;font-size:17px}
.fire-button{width:68px;height:68px;border-radius:50%;font:10px Orbitron;letter-spacing:1px;background:rgba(59,189,180,.28);margin:0 0 15px auto}
.dash-button{width:48px;height:48px;border-radius:50%;font:8px Orbitron;margin:0 0 17px 12px}
.touch-controls{display:flex}
.overlay-bottom{pointer-events:none}
@media(max-width:650px){#topbar{height:72px;padding:0 5%}
.brand-mark{font-size:7px;letter-spacing:.8px;width:27%;gap:7px}
.world-readout{font-size:10px}
.world-readout #world-name{font-size:8px;letter-spacing:1px}
.artifact-readout{width:27%}
.artifact-readout .eyebrow{font-size:6px;letter-spacing:.6px}
#artifact-slots{gap:4px!important}
#artifact-slots i{width:10px;height:10px}
.mission{top:90px;left:5%;min-width:0;padding:8px 11px}
.mission p{font-size:15px}
.health-panel{top:91px;right:5%;width:110px}
.health-panel .eyebrow{font-size:7px}
.health-panel b{font-size:10px}
.boss-panel{top:18px}
.boss-name b{font-size:12px}
.boss-name span,.boss-name em{font-size:7px}
.controls-hint{display:none}
.title-kicker{font-size:8px;letter-spacing:1.2px}
h1{letter-spacing:-3px;margin:24px 0 18px}
.title-copy{font-size:15px}
.title-footer{gap:12px;margin-top:42px;font-size:6px}
.overlay-bottom{font-size:6px;bottom:14px}
.overlay-content{width:86vw}
.touch-controls{bottom:calc(10px + env(safe-area-inset-bottom))}
.crosshair{display:none}
.prompt{top:65%}
}
@media(min-width:651px) and (hover:none){.touch-controls{display:flex}
}

